import dspy
from dspy.teleprompt.simba_utils import wrap_program


class TinyProgram(dspy.Module):
    def forward(self, question):
        return dspy.Prediction(answer="A")


program = TinyProgram()
example = dspy.Example(question="Q").with_inputs("question")


def metric(example, pred, trace=None):
    return dspy.Prediction(
        score=0.25,
        feedback="missing field_b",
        per_field={"field_a": 1.0, "field_b": 0.0},
    )


wrapped = wrap_program(program, metric)
output = wrapped(example)

print("score", output["score"])
print("output_metadata", output["output_metadata"])
print("prediction_answer", output["prediction"].answer)

assert output["score"] == 0.25
assert output["prediction"].answer == "A"
assert output["output_metadata"] == {
    "feedback": "missing field_b",
    "per_field": {"field_a": 1.0, "field_b": 0.0},
}
